        //         "I": "83946.3",
        //         "M": "83938.8",
        //         "stats": {
        //             "c": "16.41",           // contract_volume_24h
        //             "v": "1377350.271",     // notional_volume_24h
        //             "pr": "1377095.872",    // premium_volume_24h
